from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Alarm_status(EmssimCommand):
    def __init__(self, method="alarm_status", timeout=60, rpc_connection_name='localRPC'):
        super(Alarm_status, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Alarm_status, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "active alarms"):
                self._ret['alarm_info'] = data["alarm_info"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
